import{_ as a,o as t,c as i,a2 as l}from"./chunks/framework.CDU0sSpB.js";const p=JSON.parse('{"title":"2.4 验收日常内容工作","description":"用真实日常任务证明更少时间、更高准确和可恢复。","frontmatter":{"title":"2.4 验收日常内容工作","description":"用真实日常任务证明更少时间、更高准确和可恢复。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-2/2-4.md","filePath":"delivery/stage-2/2-4.md","lastUpdated":1793859143000}'),r={name:"delivery/stage-2/2-4.md"};function o(s,e,n,d,_,c){return t(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="_2-4-验收日常内容工作" tabindex="-1">2.4 验收日常内容工作 <a class="header-anchor" href="#_2-4-验收日常内容工作" aria-label="Permalink to &quot;2.4 验收日常内容工作&quot;">​</a></h1><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>用真实日常内容任务证明第二阶段的价值：用户花更少时间完成邮件、日历、文档和网页工作，同时仍能看懂、审批和恢复每一次外部操作。</p><h2 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h2><ol><li>选 10–15 个真实日常任务，覆盖邮件、日历、文档、表格和网页研究。</li><li>记录每个任务的人工时间、成功率、审批次数、失败原因和用户是否愿意再次使用。</li><li>检查每个结果是否有来源、能否核对，外部操作是否有回执。</li><li>检查不同账户和项目之间没有数据串扰，敏感信息没有出现在不该出现的地方。</li><li>修复最影响信任的问题：来源不清、审批信息不足、失败无法恢复。</li><li>只有当用户愿意把日常内容工作交给它，并且人工时间明显下降时，第二阶段才算完成。</li></ol>',5)])])}const m=a(r,[["render",o]]);export{p as __pageData,m as default};
